-- Root harness supplies an isolated empty original-credit schema and wraps rollback.
set local role postgres;
set local search_path=extensions,public;
set local timezone='UTC';
select set_config('request.jwt.claims','',true);
insert into public.organizations(id,name,gym_code,status,timezone,currency) values
 ('76000000-0000-4000-8000-000000000711','Cutover History A','CV760A','active','Asia/Kolkata','INR'),
 ('76000000-0000-4000-8000-000000000712','Cutover History B','CV760B','active','Asia/Kolkata','INR'),
 ('76000000-0000-4000-8000-000000000713','Cutover History C','CV760C','active','Asia/Kolkata','INR');
insert into public.messaging_wallets(tenant_id,balance_credits) values
 ('76000000-0000-4000-8000-000000000711',0),('76000000-0000-4000-8000-000000000712',0),('76000000-0000-4000-8000-000000000713',0);
insert into auth.users(id) values('76000000-0000-4000-8000-000000000791');
insert into public.platform_users(user_id,role,full_name,email) values('76000000-0000-4000-8000-000000000791','super_admin','Visible Conversion History','conversion760@example.test');
create temporary table conversion76_results(label text primary key,result jsonb);
grant all on conversion76_results to authenticated;
select set_config('request.jwt.claims','{"sub":"76000000-0000-4000-8000-000000000791","role":"authenticated","app_role":"super_admin"}',true);
set local role authenticated;
insert into conversion76_results select 'legacy-original',public.adjust_messaging_wallet('76000000-0000-4000-8000-000000000711',9007199254740993,'Large historical adjustment','76000000-0000-4000-8000-000000000761');
reset role;
insert into public.messaging_wallet_ledger(id,tenant_id,delta_credits,reason,created_at) values('76000000-0000-4000-8000-000000000751','76000000-0000-4000-8000-000000000711',-9007199254736493,'Historical null balance retained',statement_timestamp()+interval '1 second');
update public.messaging_wallets set balance_credits=4500 where tenant_id='76000000-0000-4000-8000-000000000711';
create temporary table conversion76_wallet_before as select to_jsonb(w) facts from public.messaging_wallets w;
create temporary table conversion76_ledger_before as select to_jsonb(l) facts from public.messaging_wallet_ledger l;
create temporary table conversion76_audit_before as select to_jsonb(a) facts from public.audit_log a;
select set_config('request.jwt.claims','',true);

postSql:
-- Run after the real migration, with only the synthetic manifest hash substituted.
set local role postgres;
set local search_path=extensions,public;
set local timezone='UTC';
select plan(18);
select is((select count(*) from public.messaging_wallets),3::bigint,'WSP-101 cutover retains every wallet including zero');
select is((select count(*) from public.messaging_wallet_ledger),2::bigint,'WSP-109 cutover creates no historical movement');
select is((select balance_paise::text from public.messaging_wallets where tenant_id='76000000-0000-4000-8000-000000000711'),'450000','WSP-101 exact net conversion');
select results_eq($q$select to_jsonb(w)-array['balance_paise','currency','original_balance_credits','conversion_paise_per_credit','conversion_currency','conversion_approval_ref','converted_at'] from public.messaging_wallets w order by tenant_id$q$,$q$select facts-'balance_credits' from conversion76_wallet_before order by facts->>'tenant_id'$q$,'WSP-109 wallet identity original created/updated timestamps unchanged at cutover');
select results_eq($q$select to_jsonb(l)-array['delta_paise','balance_after_paise','currency','original_delta_credits','original_balance_after_credits','conversion_paise_per_credit','conversion_currency','conversion_approval_ref','converted_at'] from public.messaging_wallet_ledger l order by id$q$,$q$select facts-array['delta_credits','balance_after_credits'] from conversion76_ledger_before order by facts->>'id'$q$,'WSP-109 ledger ids actor keys reason nullable refs original timestamps unchanged');
select results_eq($q$select to_jsonb(a) from public.audit_log a order by id$q$,$q$select facts from conversion76_audit_before order by facts->>'id'$q$,'WSP-109 old credit-labelled audit bytes retained no cutover audit');
select is((select delta_paise::text from public.messaging_wallet_ledger where id='76000000-0000-4000-8000-000000000751'),'-900719925473649300','WSP-101 negative large integer exact100scale');
select ok((select balance_after_paise is null and original_balance_after_credits is null from public.messaging_wallet_ledger where id='76000000-0000-4000-8000-000000000751'),'WSP-101 original historical null preserved in both units');
select set_config('request.jwt.claims','{"sub":"76000000-0000-4000-8000-000000000791","role":"authenticated","app_role":"super_admin"}',true);
set local role authenticated;
select lives_ok($q$insert into conversion76_results select 'legacy-retry',public.adjust_messaging_wallet('76000000-0000-4000-8000-000000000711',9007199254740993,'Large historical adjustment','76000000-0000-4000-8000-000000000761')$q$,'WSP-105 converted historical legacy retry succeeds');
select is((select result from conversion76_results where label='legacy-retry'),(select result from conversion76_results where label='legacy-original'),'WSP-105 original credit strings id timestamp balance unchanged beyond JSsafe');
select lives_ok($q$insert into conversion76_results select 'paise-retry',public.adjust_messaging_wallet_paise('76000000-0000-4000-8000-000000000711',900719925474099300,'INR','Large historical adjustment','76000000-0000-4000-8000-000000000761')$q$,'WSP-104 new facade replays exact converted historical request');
select is((select result->>'balanceAfterPaise' from conversion76_results where label='paise-retry'),'900719925474099300','WSP-104 exact original resulting balance instead of current450000');
select throws_ok($q$select public.adjust_messaging_wallet('76000000-0000-4000-8000-000000000711',9007199254740992,'Large historical adjustment','76000000-0000-4000-8000-000000000761')$q$,'GL068',null,'WSP-105 historical retry onecredit mismatch rejected');
select throws_ok($q$select public.adjust_messaging_wallet_paise('76000000-0000-4000-8000-000000000711',900719925474099299,'INR','Large historical adjustment','76000000-0000-4000-8000-000000000761')$q$,'GL068',null,'WSP-104 historical retry onepaisa mismatch rejected');
reset role;
select is((select count(*) from public.messaging_wallet_ledger),2::bigint,'WSP-104 two facades/rejections append no row');
select results_eq($q$select to_jsonb(a) from public.audit_log a order by id$q$,$q$select facts from conversion76_audit_before order by facts->>'id'$q$,'WSP-109 replay/refusal preserves historical audits exactly');
select ok(not exists(select 1 from public.messaging_wallet_ledger l join conversion76_ledger_before b on b.facts->>'id'=l.id::text where l.original_delta_credits::text<>b.facts->>'delta_credits' or l.original_balance_after_credits::text is distinct from b.facts->>'balance_after_credits'),'WSP-103 original credit evidence exactly records signed large values/nulls');
select ok(not exists(select 1 from public.messaging_wallets where conversion_paise_per_credit is distinct from 100 or conversion_currency is distinct from 'INR' or conversion_approval_ref is distinct from 'efff581' or converted_at is null),'WSP-103 fixed approval currency rate cutover');
select * from finish();
